&lt;body&gt;

    &lt;div class=&quot;container&quot;&gt;
        &lt;h1&gt;ABC Notation Parser&lt;/h1&gt;
        &lt;p style=&quot;font-size: 0.9rem; color: #64748b; margin-bottom: 20px;&quot;&gt;
            This parser ignores rhythm, bar lines, and formatting. It strictly extracts chords (grouped in brackets) and single notes, converting them into your VexFlow JSON arrays.
        &lt;/p&gt;

        &lt;label for=&quot;abcInput&quot;&gt;Paste ABC Notation Here:&lt;/label&gt;
        &lt;!-- Default value is a simple C major scale and some chords in ABC notation --&gt;
        &lt;textarea id=&quot;abcInput&quot;&gt;C D E F | [CEG]2 [DFA] | [EGc]4&lt;/textarea&gt;

        &lt;label&gt;Generated Custom VexFlow Array (JSON):&lt;/label&gt;
        &lt;pre id=&quot;jsonOutput&quot;&gt;&lt;/pre&gt;

        &lt;label&gt;VexFlow Visual Output:&lt;/label&gt;
        &lt;div id=&quot;notation&quot;&gt;&lt;/div&gt;
    &lt;/div&gt;

    &lt;script&gt;
        const VF = Vex.Flow;
        const colorMap = {
            &quot;c&quot;: &quot;#E74C3C&quot;, &quot;d&quot;: &quot;#E67E22&quot;, &quot;e&quot;: &quot;#F1C40F&quot;,
            &quot;f&quot;: &quot;#2ECC71&quot;, &quot;g&quot;: &quot;#3498DB&quot;, &quot;a&quot;: &quot;#9B59B6&quot;, &quot;b&quot;: &quot;#FF69B4&quot;
        };

        /**
         * Core Parser Function
         * Translates ABC text directly into [ [&quot;c/4&quot;, &quot;e/4&quot;, &quot;g/4&quot;], ... ]
         */
        function parseABCToVexFlow(abcString) {
            // Step 1: Tokenize. 
            // This Regex finds either a bracketed chord [CEG] OR a single note (A-G, a-g) with optional octave modifiers (,&#39; )
            const tokens = abcString.match(/\[[a-zA-Z,&#39;]+\]|[a-zA-Z][,&#39;]*/g) || [];

            // Step 2: Convert tokens to VexFlow arrays
            return tokens.map(token =&gt; {
                // Remove the brackets if it&#39;s a chord to just get the raw notes
                const cleanToken = token.replace(/\[|\]/g, &#39;&#39;);

                // Match individual notes within that cleaned token
                const individualNotes = cleanToken.match(/[a-zA-Z][,&#39;]*/g) || [];

                return individualNotes.map(abcNote =&gt; {
                    const noteChar = abcNote[0];
                    const modifiers = abcNote.slice(1);

                    // In ABC notation: Uppercase (C) is octave 4. Lowercase (c) is octave 5.
                    let octave = (noteChar === noteChar.toUpperCase()) ? 4 : 5;

                    // Commas (,) drop the octave. Apostrophes (&#39;) raise the octave.
                    for (let char of modifiers) {
                        if (char === &#39;,&#39;) octave--;
                        if (char === &quot;&#39;&quot;) octave++;
                    }

                    return `${noteChar.toLowerCase()}/${octave}`;
                });
            });
        }

        function renderBatch(chords) {
            const div = document.getElementById(&quot;notation&quot;);
            div.innerHTML = &quot;&quot;; 

            if (chords.length === 0) return;

            // Dynamically size the staff based on how many chords were extracted
            const staveWidth = Math.max(200, 80 + (chords.length * 60));

            const renderer = new VF.Renderer(div, VF.Renderer.Backends.SVG);
            renderer.resize(staveWidth + 40, 150);
            const context = renderer.getContext();

            const stave = new VF.Stave(10, 10, staveWidth);
            stave.addClef(&quot;treble&quot;).setContext(context).draw();

            // Map the parsed arrays into VexFlow StaveNotes
            const notes = chords.map(chordArr =&gt; {
                const staveNote = new VF.StaveNote({ keys: chordArr, duration: &quot;q&quot; });

                // Apply our custom colors
                chordArr.forEach((key, index) =&gt; {
                    const noteName = key.split(&#39;/&#39;)[0];
                    const color = colorMap[noteName] || &quot;#000000&quot;;
                    staveNote.setKeyStyle(index, { fillStyle: color, strokeStyle: color });
                });
                return staveNote;
            });

            // Draw the notes
            const voice = new VF.Voice({ num_beats: chords.length, beat_value: 4 });
            voice.addTickables(notes);
            new VF.Formatter().joinVoices([voice]).format([voice], staveWidth - 40);
            voice.draw(context, stave);
        }

        function processInput() {
            const abcText = document.getElementById(&#39;abcInput&#39;).value;

            // Run the parser
            const parsedArrays = parseABCToVexFlow(abcText);

            // Output the JSON string to the screen so you can see the data structure
            document.getElementById(&#39;jsonOutput&#39;).textContent = JSON.stringify(parsedArrays, null, 2);

            // Render the visual representation
            renderBatch(parsedArrays);
        }

        // Add event listeners to process automatically when you type
        document.getElementById(&#39;abcInput&#39;).addEventListener(&#39;input&#39;, processInput);

        // Run once on load
        processInput();

    &lt;/script&gt;
